#include <bits/stdc++.h>
using namespace std;
#define int long long

const int MAX_SIZE = 100000 + 5;
const int MODULUS = 1000000007;
int array_dp[17];

int recursiveSolve(int value, int depth) {
    if (depth == 0) {
        return (value == 0) ? 0 : MODULUS;
    }
    int divisionCount = value / array_dp[depth];
    if (value % array_dp[depth] == 0) return depth * divisionCount;
    int optionA = recursiveSolve(abs(value - array_dp[depth] * (divisionCount + 1)), depth - 1) + depth;
    int optionB = recursiveSolve(value - array_dp[depth] * divisionCount, depth - 1);
    return min(depth * (divisionCount + 1) + optionA - depth, depth * divisionCount + optionB);
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    array_dp[1] = 1;
    for (int i = 2; i < 17; ++i) {
        array_dp[i] = array_dp[i - 1] * 10 + 1;
    }
    int input_value; cin >> input_value;
    cout << recursiveSolve(input_value, 16) << "\n";
    return 0;
}
